def experience(slug,items):
    data=DATA.get(slug)
    if not data:return ''
    photos=PHOTOS[slug]
    phases=[t('Nos cuentas','Cóntasnos'),t('Preparamos','Preparamos'),t('Lo cuidamos','Coidámolo'),t('Seguimos en casa','Seguimos na casa')]
    # La alimentación es una consulta de compra, no una intervención sobre el perro.
    if slug=='comida-especializada':phases=[t('Nos cuentas','Cóntasnos'),t('Vemos opciones','Vemos opcións'),t('Resolvemos dudas','Resolvemos dúbidas'),t('Lo organizamos','Organizámolo')]
    figures=''.join(f'<img class="journey-image {"on" if i==0 else ""}" data-frame="{i}" aria-hidden="{str(i!=0).lower()}" src="assets/img/real/{photo}.webp" alt="{t("Un momento del día a día en Pelucans","Un momento do día a día en Pelucans")}" loading="lazy">' for i,photo in enumerate(photos))
    links=''.join(f'<a href="#momento-{slug}-{i+1}" data-journey-link="{i}" {"aria-current=step" if i==0 else ""}><span>0{i+1}</span><b>{phase}</b></a>' for i,phase in enumerate(phases))
    cards=[]
    for i,((title,original),(es,gl,points,gpoints)) in enumerate(zip(items,data)):
        paragraph=t(es,gl)
        bullets=''.join(f'<li>{t(a,b)}</li>' for a,b in zip(points.split('|'),gpoints.split('|')))
        cards.append(f'<article class="journey-chapter {"on" if i==0 else ""}" id="momento-{slug}-{i+1}" data-chapter="{i}"><div class="chapter-heading"><span class="chapter-number">0{i+1}</span><div><span class="eyebrow">{phases[i]}</span><h3>{escape(title)}</h3></div></div><img class="chapter-mobile-photo" src="assets/img/real/{photos[i]}.webp" alt="{t("Un momento del día a día en Pelucans","Un momento do día a día en Pelucans")}" loading="lazy"><p class="chapter-lead">{escape(original)}</p><p>{paragraph}</p><div class="chapter-focus"><span>{t("Ponemos atención en","Poñemos atención en")}</span><ul>{bullets}</ul></div></article>')
    return f'<div class="care-journey"><nav class="journey-index" aria-label="{t("Los momentos de su cuidado","Os momentos do seu coidado")}">{links}</nav><div class="journey-layout"><div class="journey-scene"><div class="journey-photo">{figures}<div class="journey-photo-label"><span>{t("Del día a día en el salón","Do día a día no salón")}</span><b><span data-journey-count>01</span> / 04</b></div></div><div class="journey-promise"><img src="assets/img/real/perfil.webp" alt="" width="150" height="150"><p>{t("Su ritmo es parte del cuidado.","O seu ritmo é parte do coidado.")}<small>{t("Atención individual · Decisiones contigo","Atención individual · Decisións contigo")}</small></p></div></div><div class="journey-chapters">'+''.join(cards)+'</div></div></div>'
